int main(int argc, char** argv) {
    const std::string path = argc > 1 ? argv[1] : "roundtrip.pcap";
    std::printf("== Nasdaq.IseOptions.OrderComboFeed.Itch.v1.1 (write and read)\n");

    try {
        if (!write(path)) {
            std::printf("FAIL: could not write %s\n", path.c_str());
            return 1;
        }
    } catch (const std::exception& error) {
        std::printf("FAIL: writing: %s\n", error.what());
        return 1;
    }

    const int failures = read(path);
    std::printf(failures == 0 ? "PASS\n" : "FAIL\n");
    return failures == 0 ? 0 : 1;
}
